/bin/bash -c "awk '
function fail(message) {
  print \"AI Usage validation failed: \" message > \"/dev/stderr\"
  exit 1
}
function trim(value) {
  sub(/"'^[[:space:]]+/, "", value)
  sub(/[[:space:]]+$/, "", value)
  return value
}
BEGIN {
  expected[1] = "breakdown"
  expected[2] = "design"
  expected[3] = "testing"
  expected[4] = "implementation"
  expected[5] = "review"
}
/''^## / {
  headings++
  heading[headings] = $0
  if (headings == 1 && $0 != "## Motivation") fail("first section is not Motivation")
  if (headings == 2 && $0 != "## Changes") fail("second section is not Changes")
  if (headings == 3 && $0 != "## Testing") fail("third section is not Testing")
  if (headings == 4 && $0 != "## AI Usage") fail("fourth section is not AI Usage")
}
$0 == "<!-- ai-declaration:start -->" { starts++ }
$0 == "<!-- ai-declaration:end -->" { ends++ }
$0 == "**AI declaration** ([v0.1.2](https://ai-declaration.md/en/0.1.2)): `auto`" { declarations++ }
index($0, "[![AI-DECLARATION: auto](https://img.shields.io/badge/") && index($0, "AI--DECLARATION-auto-ede9fe?labelColor=ede9fe)](https://ai-declaration.md)") { badges++ }
/''^'"\\| (breakdown|design|testing|implementation|review) \\|/ {
  fields = split("'$0, row, "|")
  if (fields != 6) fail("stage row does not have four cells")
  stages++
  stage = trim(row[2])
  level = trim(row[3])
  involvement = trim(row[4])
  decision = trim(row[5])
  if (stage != expected[stages]) fail("stage order or identifier is invalid")
  if (level != "auto") fail("stage " stage " is not auto")
  if (involvement != "100%") fail("stage " stage " is not 100%")
  words = split(decision, word, /[[:space:]]+/)
  if (decision == "" || words > 40) fail("stage " stage " decision record is empty or exceeds 40 words")
}
END {
  if (headings != 4) fail("expected exactly four second-level sections")
  if (starts != 1 || ends != 1) fail("AI-DECLARATION markers must each occur exactly once")
  if (badges != 1 || declarations != 1) fail("badge or declaration line is missing or duplicated")
  if (stages != 5) fail("expected exactly five stage rows")
  print "AI Usage validation passed: section order, one marker pair, auto badge/declaration, five ordered auto rows at 100%, and decision records within 40 words."
}
'"' evals/files/ai-provenance/pr-body.md"

